from abc import ABC, abstractmethod

# Abstract class SortAlgorithm
class SortAlgorithm(ABC):
    @abstractmethod
    def compare(self, a, b):
        pass

    @abstractmethod
    def swap(self, a, b):
        pass


# Concrete subclass BubbleSort
class BubbleSort(SortAlgorithm):
    def sort(self, arr):
        n = len(arr)
        for i in range(n):
            for j in range(0, n - i - 1):
                if self.compare(arr[j], arr[j + 1]) > 0:
                    self.swap(arr[j], arr[j + 1])


# Concrete subclass SelectionSort
class SelectionSort(SortAlgorithm):
    def sort(self, arr):
        n = len(arr)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(arr[j], arr[min_idx]) < 0:
                    min_idx = j
            self.swap(arr[i], arr[min_idx])


# Test the implementation
if __name__ == "__main__":
    arr1 = [64, 34, 25, 12, 22, 11, 90]
    bubble_sort = BubbleSort()
    bubble_sort.sort(arr1)
    print("Sorted array using BubbleSort:", arr1)

    arr2 = ['dog', 'cat', 'apple', 'banana', 'cherry']
    selection_sort = SelectionSort()
    selection_sort.sort(arr2)
    print("Sorted array using SelectionSort:", arr2)
